function schoolBadge(id){const item=SCHOOL_ASSETS[id];const short=item?.short||id.toUpperCase().slice(0,4);return '<span class="school-mark '+(item?.dark?'dark-logo':'')+'" aria-hidden="true"><span class="school-fallback">'+short+'</span>'+(item?.path?'<img src="'+item.path+'" alt="" loading="lazy" decoding="async">':'')+'</span>'}
document.addEventListener("error",event=>{if(event.target.matches?.(".school-mark img"))event.target.remove()},true);
